<section class="card form-section"><div class="between"><div><p class="eyebrow">SEGUIMIENTO DEL ACUERDO</p><h2><?= e(taskLabel($contract)) ?></h2></div><span class="badge <?= $contract['due_date'] && $contract['due_date'] < date('Y-m-d') ? 'observed' : 'approved' ?>"><?= e(dueLabel($contract['due_date'])) ?></span></div><div class="tracking-grid"><div><small>Responsable de la tarea</small><p><?= e($contract['assignee_name'] ?? 'Recorrido completado') ?></p></div><div><small>Fecha límite de la tarea</small><p><?= e($contract['due_date'] ?? '—') ?></p></div><div><small>Plazo por etapa</small><p><?= (int) $contract['review_days'] ?> días calendario</p></div></div>
<?php if ($contract['status'] !== 'signed' && ($user['role'] === 'admin' || ($user['role'] === 'commercial' && $contract['owner_id'] === $user['id']))): ?><details class="action-details"><summary>Organizar responsable y fecha límite</summary><form method="post" class="tracking-form"><?= csrfField() ?><input type="hidden" name="action" value="assign_task"><input type="hidden" name="contract_id" value="<?= e($contract['id']) ?>"><div class="field"><label>Responsable<select name="assignee_id"><?php foreach ($eligibleAssignees as $profile): ?><option value="<?= e($profile['id']) ?>" <?= $profile['id'] === $contract['assignee_id'] ? 'selected' : '' ?>><?= e($profile['name']) ?></option><?php endforeach ?></select></label></div><div class="field"><label>Fecha límite<input type="date" name="due_date" value="<?= e($contract['due_date']) ?>" required></label></div><button type="submit" class="btn btn-secondary">Guardar seguimiento</button></form><small>La asignación se limita al área de la tarea actual. El siguiente paso recibe su propio plazo.</small></details><?php endif ?>
</section>
